from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Button, Color, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
motoEsquerda = Motor(Port.A, Direction.COUNTERCLOCKWISE)
motorDireita = Motor(Port.E, Direction.CLOCKWISE)
robo = DriveBase(motoEsquerda, motorDireita, 62, 144)
garraEsquerda = Motor(Port.D, Direction.COUNTERCLOCKWISE)
garraDireita = Motor(Port.F, Direction.CLOCKWISE)
miss_C3_A3o = 1

def menu():
    global miss_C3_A3o
    prime_hub.display.number(miss_C3_A3o)
    motoEsquerda.control.limits(acceleration=2000)
    robo.settings(straight_speed=500)
    robo.settings(straight_acceleration=500)
    robo.settings(turn_rate=300)
    robo.settings(straight_speed=400)
    if Button.LEFT in prime_hub.buttons.pressed():
        prime_hub.speaker.beep(880, 120)
        if miss_C3_A3o > 1:
            miss_C3_A3o = miss_C3_A3o - 1
        wait(200)
    if Button.CENTER in prime_hub.buttons.pressed():
        prime_hub.speaker.beep(784, 120)
        prime_hub.speaker.beep(988, 120)
        prime_hub.speaker.beep(1175, 149)
        if miss_C3_A3o == 1:
            missao_1()
        elif miss_C3_A3o == 2:
            _missao_2()
        elif miss_C3_A3o == 3:
            missao_3()
        elif miss_C3_A3o == 4:
            missao_4()
        else:
            missao_5()
        prime_hub.speaker.beep(1047, 200)
        wait(50)
        prime_hub.speaker.beep(1319, 200)

def _missao_2():
    pass

def missao_4():
    pass

def missao_5():
    pass

def missao_3():
    pass

def teste_de_bateria():
    if prime_hub.battery.voltage() >= 8200:
        prime_hub.light.on(Color.GREEN)
    elif 7500 <= prime_hub.battery.voltage() < 8200:
        prime_hub.light.on(Color.YELLOW)
    else:
        prime_hub.light.on(Color.RED)

def missao_2():
    pass

def missao_1():
    robo.straight(519)
    robo.turn(-90)
    robo.stop()
    robo.straight(113)
    garraDireita.run_angle(100, 76)
    robo.straight(-108)


# The main program starts here.
prime_hub.system.set_stop_button(Button.BLUETOOTH)
teste_de_bateria()
motorDireita.reset_angle(0)
wait(500)
motorDireita.hold()
robo.use_gyro(True)
prime_hub.speaker.beep(880, 120)
wait(40)
prime_hub.speaker.beep(1320, 120)
wait(40)
prime_hub.speaker.beep(1760, 180)
while True:
    menu()
